from django.apps.registry import Apps
from django.db import migrations, models
from django.db.backends.base.schema import BaseDatabaseSchemaEditor
from django.db.models import Q

# Template media were generated by AI before provenance existed (ADR-059). The
# migration runs as the table owner (the postgres superuser), so FORCE RLS on
# media_mediaasset does not hide other tenants' rows from this update. Files
# already processed keep no XMP; only development instances have them.
TEMPLATE_KEYS = Q(idempotency_key__startswith="template:") | Q(
    idempotency_key__startswith="template-photo:"
)


def mark_template_media(apps: Apps, _schema_editor: BaseDatabaseSchemaEditor) -> None:
    MediaAsset = apps.get_model("media", "MediaAsset")
    MediaAsset._default_manager.filter(TEMPLATE_KEYS).update(ai_origin="generated")


class Migration(migrations.Migration):
    dependencies = [("media", "0007_media_reference_allows_erasure")]

    operations = [
        migrations.AddField(
            model_name="mediaasset",
            name="ai_origin",
            field=models.CharField(
                choices=[("none", "Zwykłe medium"), ("generated", "Wygenerowane przez AI")],
                default="none",
                max_length=16,
            ),
        ),
        migrations.RunPython(mark_template_media, migrations.RunPython.noop),
    ]
